export function deriveNextValidAccount(seed: Uint8Array, startIndex: number): DerivedAccount {
  assertAddressIndexInRange(startIndex);

  for (let index = startIndex; index <= MAX_ADDRESS_INDEX; index += 1) {
    try {
      return deriveAccountAt(seed, index);
    } catch (error) {
      // BIP-32: «one should proceed with the next value for **i**», donde `i` es el índice
110→      // *del nivel que falló*. Sólo el último nivel del path depende del `address_index`, así
      // que sólo ese caso se resuelve avanzando al índice siguiente.
      if (
        error instanceof InvalidChildKeyError &&
        error.depth === ADDRESS_INDEX_DEPTH &&
        error.index === index
