120→      // BIP-44, su entrada HMAC no depende del `address_index` y reintentar reproduciría el
      // mismo cómputo 2³¹ veces. Es un fallo crítico (~2⁻¹²⁷) y se aborta (HU-06-01 RN-11).
      if (error instanceof InvalidChildKeyError) {
        throw new AppError(
          'INTERNAL_ERROR',
          `Derivación BIP-44 imposible: el nivel fijo ${error.depth ?? '?'} del path ` +
            `${ETHEREUM_BASE_PATH} produce una clave BIP-32 inválida con este seed.`,
        );
      }
